def polygon(sz, points):
 im=Image.new('L',(sz[0]*8,sz[1]*8)); ImageDraw.Draw(im).polygon([(round(x*8),round(y*8))for x,y in points],fill=255)
 return np.asarray(im.resize(sz,Image.Resampling.LANCZOS),dtype=np.uint8)
records=[]
for name in ['mace','firebird','livinglight','seapearl']:
 src=Image.open(doc/'Sources'/f'{name}_native.png').convert('RGBA');a=np.array(src); rgb=a[:,:,:3].astype(float)
 if name=='seapearl':
  body=polygon(src.size,paths['seapearl_body'])
  chain=np.maximum(polygon(src.size,paths['seapearl_left_chain']),polygon(src.size,paths['seapearl_right_chain']))
  warmth=np.clip((rgb[:,:,0]-rgb[:,:,2]*1.05-8)/35,0,1)
  chain=(chain*warmth).astype(np.uint8)
  mask=np.maximum(body,chain)
 elif name=='firebird':
  contour=polygon(src.size,paths[name])
  warmth=np.clip((rgb[:,:,0]-rgb[:,:,2]*1.25-12)/46,0,1)
  luminance=np.clip((rgb[:,:,0]-45)/48,0,1)
  heat=np.maximum(np.minimum(warmth,luminance),((rgb[:,:,0]>220)&(rgb[:,:,1]>170)).astype(float))
  mask=(contour*heat).astype(np.uint8)
 else:mask=polygon(src.size,paths[name])
 if name=='firebird':
  connected,count=ndimage.label(mask>10)
  sizes=np.bincount(connected.ravel());sizes[0]=0
  kept=connected==sizes.argmax()
  mask=np.where(ndimage.binary_dilation(kept,iterations=1),mask,0).astype(np.uint8)
 elif name in ('mace','livinglight'):
  # Traced contours follow the object/backing transition; contract less than one
  # native pixel to avoid retaining antialiased blue/red medallion fringes.
  inside=mask>127; distance=ndimage.distance_transform_edt(inside)
  alpha_edge=np.clip(distance-.65,0,1)
  mask=np.minimum(mask,(alpha_edge*255).astype(np.uint8))
 a[:,:,3]=np.minimum(a[:,:,3],mask)
 a[a[:,:,3]>=240,3]=255
 a[a[:,:,3]<4,3]=0
 # Keep original RGB byte-for-byte; only alpha and transparent-margin bounds change.
 ys,xs=np.where(a[:,:,3]>0); box=(int(xs.min()),int(ys.min()),int(xs.max())+1,int(ys.max())+1)
 final=Image.fromarray(a).crop(box)
 assert np.array_equal(np.asarray(final)[:,:,:3],np.asarray(src)[box[1]:box[3],box[0]:box[2],:3])
 final.save(out/f'booster_{name}_r9.png')
 Image.fromarray(mask).save(doc/'QA'/f'{name}_mask.png')
 for color,bg in [('black',(0,0,0,255)),('white',(255,255,255,255)),('magenta',(225,0,255,255))]:
  sheet=Image.new('RGBA',(final.width+20,final.height+20),bg);sheet.alpha_composite(final,(10,10));sheet.convert('RGB').resize((sheet.width*2,sheet.height*2)).save(out/f'{name}_{color}.png')
 records.append({'name':name,'source':f'Sources/{name}_native.png','sourceCrop':box,'size':list(final.size),'opaquePixels':int((np.array(final)[:,:,3]==255).sum()),'partialPixels':int(((np.array(final)[:,:,3]>0)&(np.array(final)[:,:,3]<255)).sum()),'rgbUnchanged':True})
(out/'records.json').write_text(json.dumps(records,indent=2))
